   "q": "下列情形所反映的权利类别与其他三项不同的是（ ）",
   "options": [
    "小张向老刘借款6000 元，并将祖传玉镯交与老刘，二人约定三年内还钱取镯，否则老刘有权变卖玉镯获偿",
    "某公司在地方政府组织的拍卖会上拍得一块土地，用于日后的商业开发",
    "李女士送修电动车，后拒不支付修车费，店老板遂留置电动车",
    "某银行向购房人王先生发放了一笔按揭贷款，贷款期限25 年"
   ],
   "answer": 1,
   "explain": "】本题考查法律常识。 A 项,《物权法》第二百零八条规定：“为担保债务的履行，债务人或者第三人将其动 产出质给债权人占有的，债务人不履行到期债务或者发生当事人约定的实现质权 的情形，债权人有权就该动产优先受偿。”选项中，为担保债务的履行，小张将 祖传玉镯交与老刘，并且约定如未来小张不能履行到期债务，则老刘有权变卖玉 镯并获偿。该情形符合《物权法》中质权的相关规定，而质权属于担保物权； B 项，《物权法》第一百三十五条规定：“建设用地使用权人依法对国家所有的土地享 有占有、使用和收益的权利，有权利用该土地建造建筑物、构筑物及其附属设施。” 故某公司在地方政府组织的拍卖会上拍得土地，用于日后的商业开发，这属于建 设用地使用权。而建设用地使用权属于用益物权； C 项，《物权法》第二百三十条规定：“债务人不履行到期债务，债权人可以留置已经 合法占有的债务人的动产，并有权就该动产优先受偿。”李女士送",
