   "answer": 3,
   "explain": "】本题考查法律常识。 A 项，根据《中华人民共和国劳动合同法》第十条规定，用人单位与劳动者在用工前订 立劳动合同的，劳动关系自用工之日起建立。王某3 月1 日与用人单位签订劳动 合同，3 月5 日正式上班，劳动关系应自3 月5 日起建立； B 项，根据《中华人民共和国劳动合同法》第九条规定，用人单位招用劳动者，不得扣 押劳动者的居民身份证和其他证件，不得要求劳动者提供担保或者以其他名义向 劳动者收取财物。李某在签订劳动合同时，用人单位不得收取押金； C 项，根据《中华人民共和国劳动合同法》第六十九条规定：非全日制用工双方当事人 可以订立口头协议。赵某在甲公司任职，同时在乙公司做兼职翻译，乙公司不一 定要与赵某订立书面劳动合同，口头协议即可； D 项，根据《中华人民共和国劳动合同法》第三十四条规定，用人单位发生合并或者分 立等情况，原劳动合同继续有效，劳动合同由承继其权利和义务的用人单位继续",
