   "explain": "】本题考查经济常识。 全国服务电话：400-6353-606 A 项，《关于小额贷款公司试点的指导意见》规定：“小额贷款公司是由自然人、企业 法人与其他社会组织投资设立，不吸收公众存款，经营小额贷款业务的有限责任 公司或股份有限公司。”故小额贷款公司不能承接城乡居民储蓄存款业务，因此 对应错误； B 项，《保险法》第九十五条规定：“保险人不得兼营人身保险业务和财产保险业务。” 人寿保险公司的业务属于人身保险业务，而医疗责任保险业务属于财产保险业务， 根据保险人不得兼营人身保险业务和财产保险业务的规定，人寿保险公司不能经 营医疗责任保险业务，因此对应错误； C 项，中国出口信用保险公司，简称中国信保，其业务范围包括：中长期出口信用保险 业务；海外投资保险业务；短期出口信用保险业务；国内信用保险业务；与出口 信用保险相关的信用担保业务和再保险业务等。由此可见，海外投资保险属于该 公",
