   "id": "xc-2018-gk-dishi-15",
   "module": "changshi",
   "q": "下列研究课题与其查阅的主要参考文献对应错误的是（ ）",
   "options": [
    "商周时代的艺术成就——《中国青铜时代》",
    "明末中西文化交流史——《利玛窦与中国》",
    "晚清的政治改良运动——《从甲午到戊戌》",
    "南宋都城的城市建设——《从平城到洛阳》"
   ],
   "answer": 3,
   "explain": "】本题考查历史常识。《从平城到洛阳》这本书主要是以拓跋魏建立的首都平城及 孝文帝迁都后的洛阳为基点，讨论拓跋魏进入长城后近一个世纪文化变迁的历程。北 宋灭亡后赵构在南方建立了南宋，其都城为临安（今浙江杭州），因此研究其都城的 城市建设选择文献《从平城到洛阳》是错误的； A 项，夏商周在中国历史上被称为青铜时代，商周时期是青铜发展的繁盛时期，故研 究商周时期的艺术成就选择《中国青铜时代》是正确的； B 项，利玛窦是意大利的传教士，明朝万历年间（明末）来到中国传教。他是最早在中 国传教的传教士之一，也是第一位阅读钻研中国文学典籍的西方学者。故研究明 末中西文化交流史查阅《利玛窦与中国》是正确的； C 项，中日甲午战争后，帝国主义掀起了瓜分中国的狂潮，使中华民族进一步觉醒，以 康有为、梁启超为代表的维新派人士通过光绪帝进行倡导学习西方，提倡科学文 化，改革政治、教育制度，发展农、工、商业等的政治",
