   "id": "xc-2018-gk-dishi-16",
   "module": "changshi",
   "q": "美国社会学家帕森斯认为，在公元前的第一个千年之内，“哲学的突破”以截然不同的方式分别发生在希腊、以色列、印度和中国等地。下列思想观点产生于这一时代的是（ ）",
   "options": [
    "师夷长技，中体西用",
    "人民为主，工商皆本",
    "致虚守静，道法自然",
    "心外无物，心外无理"
   ],
   "answer": 2,
   "explain": "】本题考查历史常识。 A 项，“师夷长技，中体西用”是洋务运动提出的口号，是19 世纪60 到90 年代晚清 洋务派所进行的一场引进西方军事装备、机器生产和科学技术以维护清朝统治的 自救运动； 全国服务电话：400-6353-606 B 项，明末清初的王夫之、黄宗羲和顾炎武之所以被称为进步思想家，主要是因为他们 反对君主专制独裁，主张“人民为主”，主张“工商皆本”，强调“经世致用”； C 项，“道法自然，致虚守静”取自《道德经》，《道德经》是春秋时期老子的哲学作 品。老子，姓李名耳，约出生于公元前571 年，逝世于公元前471 年，在公元前 的第一个千年之内； D 项，“心外无物，心外无理”为王阳明提出的心学思想。王守仁，别号阳明，明代著 名的思想家、文学家、哲学家和军事家，陆王心学之集大成者，精通儒家、道家 和佛家学说，不属于公元前的第一个千年之内。 故正确答案为C。",
   "year": 2018,
   "exam_type": "gk-dishi",
   "exam_volume": "行测",
   "topic": "",
