   "answer": 0,
   "explain": "】本题考查文化常识。唐卡不是朝鲜族的艺术，是藏族文化中一种独具特色的绘画 艺术形式，具有鲜明的民族特点、浓郁的宗教色彩和独特的艺术风格，用明亮的色彩 描绘出神圣的佛的世界。颜料传统上是全部采用金、银、珍珠、玛瑙、珊瑚、松石、孔 雀石、朱砂等珍贵的矿物宝石和藏红花、大黄、蓝靛等植物为原料，以示其神圣。这 些天然原料保证了所绘制的唐卡色泽鲜艳，璀璨夺目，虽经几百年的岁月，仍是色泽 艳丽明亮，因此被誉为中国民族绘画艺术的珍品，被称为藏族的“百科全书”，也是 中华民族民间艺术中弥足珍贵的非物质文化遗产。 故正确答案为A。",
