   "id": "xc-2018-gk-dishi-39",
   "module": "yanyu",
   "q": "漆画有其他画种达不到的效果，同时也有它的______。它不能像油画、水粉画那样自由地运用冷暖色彩，不能像素描那样丰富地运用明暗层次，不善于逼真地、______地再现对象。事实上，在似与不似之间表现对象，才是漆画最______的地方。依次填入画横线部分最恰当的一项是（ ）",
