   "id": "xc-2018-gk-dishi-104",
   "module": "panduan",
   "q": "自上世纪50 年代以来，全球每年平均爆发的大型龙卷风的次数从10 次左右上升至15 次。与此同时，人类活动激增，全球气候明显变暖，有人据此认为，气候变暖导致龙卷风爆发次数增加。以下哪项如果为真，不能削弱上述结论（ ）",
   "options": [
    "龙卷风的类型多样，全球变暖后，小型龙卷风出现的次数并没有明显的变化全国服务电话：400-6353-606",
    "气候温暖是龙卷风形成的一个必要条件，几乎所有龙卷风的形成都与当地较高的温度有关",
    "尽管全球变暖，龙卷风依然最多地发生在美国的中西部地区，其他地区的龙卷风现象并不多见",
    "龙卷风是雷暴天气（即伴有雷击和闪电的局地对流性天气）的产物，只要在雷雨天气下出现极强的空气对流，就容易发生龙卷风"
   ],
   "answer": 1,
   "explain": "】削弱论证，选非题。论点：气候变暖导致龙卷风爆发次数增加。 A 项，全球变暖，小型龙卷风出现的次数没有明显变化，虽未证明龙卷风总数量的变 化，但仍说明部分龙卷风数量未受影响，有一定的削弱作用，排除； B 项，强调龙卷风的形成与气候温暖有必然关系，可以加强论点，当选； C 项，气候变暖是全球现象，并未导致除美国中西部地区以外的其他地区龙卷风次数 的增加，削弱，排除； D 项，雷暴天气是龙卷风增多的原因，削弱了与气候的绝对关系，排除。 故正确答案为B。",
