   "id": "xc-2018-gk-dishi-105",
   "module": "ziliao",
   "q": "日前，研究人员发明了一种弹性超强的新材料，这种材料可以由1英寸被拉伸到100英寸以上，同时这一材料2018年国家公务员录用考试《行测》真题（地市级网友回忆版）可以自行修复且能通过电压控制动作。因此研究者认为，利用该材料可以制成人工肌肉，替代人体肌肉，从而为那些肌肉损伤后无法恢复功能的患者带来福音。以下哪项如果为真，不能支持研究者的观点？",
