   "module": "yanyu",
   "q": "在执行任务期间，“反潜持续追踪无人艇”一旦发现目标的______，就会使用声纳系统对目标进行______定位并跟踪，同时借助传感器技术进行信息______。逼近目标时，无人艇会通过声学图像，确定目标潜艇的型号等信息，再将数据传输到反潜指挥中心，由中心指派就近的反潜平台赶往目标海域，摧毁敌艇。依次填入画横线部分最恰当的一项是（ ）",
