   "answer": 3,
   "explain": "】将选项与原文一一对应，本题为选非题。 A 项，对应第④段 “PIEZO2 基因早就有人研究过，它被认为和触觉的形成有关。小鼠 体内也有一个类似的基因”可知，PIEZO2 并非人类特有的基因，说法正确，排除； B 项，对应第⑧段 “伯内曼教授认为PIEZO2 基因在人类群体中还存在不同的亚型”可 知，说法正确，排除； C 项，对应第④段“两人最初是因为髋关节、手指、脚趾和脊柱都存在不同程度的变 形……发现两人的PIEZO2 基因均出现了变异，导致这一基因失去了活性”可知， 说法正确，排除； D 项，“会因胚胎发育过程中受损而出现变异”属于无中生有，说法错误，当选。 故正确答案为D。",
