   "id": "xc-2018-gk-fsheng-91",
   "module": "panduan",
   "q": "人耳对一个声音的感受性会因另一个声音的存在而发生改变。一个声音能被人耳听到的最低值会因另一声音的出现而提高，这种现象就是听觉掩蔽。根据上述定义，下列符合听觉掩蔽的是（ ）",
   "options": [
    "吵闹的课间，老师得大声说话，同学们才能听到",
    "长时间戴耳机听音乐，会觉得听到的音量逐渐变小",
    "人类无法听到蝙蝠等动物发出来的超声波",
    "安静的房间内，我们能够听到闹钟“滴答”的声音"
   ],
   "answer": 0,
   "explain": "】定义判断。关键词：人耳对一个声音的感受性会因另一个声音的存在而发生改变； 被人耳听到的最低值会因另一个声音的出现而提高。 A 项，受到吵闹的课间的影响学生能听到声音的最低值提高了，因此老师需要大声说 话才能被学生听到，符合定义，当选； B 项，只有音乐，没有另一个声音影响，不符合定义，排除； C 项，只是对一个声音的论述，没有其他声音的影响，不符合定义，排除； D 项，只有闹钟的声音，没有其他的声音的干扰，不符合定义，排除。 故正确答案为A。",
   "year": 2018,
   "exam_type": "gk-fsheng",
   "exam_volume": "行测",
   "topic": "",
   "src": "真题·PDF",
   "url": ""
