   "q": "异质型人力资本是指某个特定历史阶段中具有边际收益递增生产力形态的人力资本，表现为拥有者所具有的2018年国家公务员录用考试《行测》真题（副省级网友回忆版）独特能力，这些能力主要包括：综合协调能力、判断决策能力、学习创新能力和承担风险能力等。根据上述定义，下列不涉及异质型人力资本的是：",
