   "id": "xc-2018-gk-fsheng-115",
   "module": "ziliao",
   "q": "某次会议讨论期间，甲、乙、丙、丁、戊被安排在一张圆桌前进行讨论，圆桌边放着标有1～5号的五张座椅(未必按序排列)。实际讨论时，甲、乙、丙、丁、戊5人均未按顺序坐在1～5号的座椅上，已知：（1）甲坐在1号座椅右边第二张座椅上；2018年国家公务员录用考试《行测》真题（副省级网友回忆版）（2）乙坐在5号座椅左边第二张座椅上；（3）丙坐在3号座椅左边第一张座椅上；（4）丁坐在2号座椅左边第一张座椅上。如果丙坐在1号座椅上，则可知甲坐的是哪个座椅？",
